# Test helpers. Each test file sources this, calls t_setup, then asserts.
T_HOME=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
T_FAIL=0
T_PASS=0

t_setup() {
  T_WORK=$(mktemp -d)
  trap 't_cleanup' EXIT
  export ROLLOUT_WORK_DIR="$T_WORK/work"
  export ROLLOUT_OUT_DIR="$T_WORK/out"
  export ROLLOUT_HOSTS_FILE="$T_HOME/conf/hosts.conf"
  export ROLLOUT_RELEASE_DIR="$T_HOME/releases"
  export CFGSVC_HOME="$T_WORK/cfgsvc"
  mkdir -p "$CFGSVC_HOME"
}

t_cleanup() { [ -n "${T_WORK:-}" ] && rm -rf "$T_WORK"; }

# Loads the libraries into the test shell (for unit tests).
t_source_libs() {
  export LC_ALL=C.UTF-8
  export ROLLOUT_HOME="$T_HOME"
  . "$T_HOME/steps/_env.sh"
}

rollout() { "$T_HOME/bin/rollout" "$@"; }

ok()   { T_PASS=$((T_PASS + 1)); printf 'ok   - %s\n' "$1"; }
fail() { T_FAIL=$((T_FAIL + 1)); printf 'FAIL - %s\n' "$1"; [ -n "${2:-}" ] && printf '       %s\n' "$2"; return 0; }

assert_eq() {
  if [ "$2" = "$3" ]; then ok "$1"; else fail "$1" "expected [$3] got [$2]"; fi
}

assert_contains() {
  if printf '%s' "$2" | grep -qF -- "$3"; then ok "$1"; else fail "$1" "missing [$3]"; fi
}

assert_rc() {
  if [ "$2" -eq "$3" ]; then ok "$1"; else fail "$1" "expected exit $3 got $2"; fi
}

t_done() {
  printf '# %s: %d passed, %d failed\n' "$(basename "$0")" "$T_PASS" "$T_FAIL"
  [ "$T_FAIL" -eq 0 ]
}
# audit.sh — rollout history: one line per finished rollout.
# release|mark|hosts|changes

history_file() { printf '%s/history.log' "$OUT_DIR"; }

history_add() {
  ensure_dir "$OUT_DIR"
  printf '%s|%s|%s|%s\n' "$1" "$2" "$3" "$4" >> "$(history_file)"
}

history_show() {
  local f
  f=$(history_file)
  [ -f "$f" ] || return 0
  awk -F'|' '{ printf "%-14s %-9s %3s hosts %3s changes\n", $1, $2, $3, $4 }' "$f"
}
# common.sh — logging, configuration loading and small guards shared by
# the wrapper and every step script.

log()  { printf '[%s] %s\n' "${ROLLOUT_STEP:-rollout}" "$*" >&2; }
warn() { printf '[%s] warn: %s\n' "${ROLLOUT_STEP:-rollout}" "$*" >&2; }
die()  { printf '[%s] error: %s\n' "${ROLLOUT_STEP:-rollout}" "$*" >&2; exit "${2:-1}"; }

load_conf() {
  local f="$ROLLOUT_HOME/conf/rollout.conf"
  [ -r "$f" ] || die "missing config $f"
  # shellcheck disable=SC1090
  . "$f"
}

require_file() {
  [ -f "$1" ] || die "${2:-file} not found: $1"
  [ -r "$1" ] || die "${2:-file} not readable: $1"
}

ensure_dir() {
  mkdir -p "$1" 2>/dev/null || die "cannot create directory $1"
  [ -w "$1" ] || die "directory not writable: $1"
}

# Per-release working area: $WORK_DIR/<release id>
run_dir() { printf '%s/%s' "$WORK_DIR" "$1"; }

host_out() { printf '%s/hosts/%s/app.conf' "$OUT_DIR" "$1"; }

